namespace sv_84982d14493d47a5a0db927e59190450.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service that holds per-circuit theme state.
/// All interactive components subscribe to OnChange to re-render when theme updates.
/// </summary>
public class ThemeService
{
    private Theme _currentTheme = Theme.System;
    private string _accentColor = "#0d6efd";

    public Theme CurrentTheme
    {
        get => _currentTheme;
        set
        {
            if (_currentTheme == value) return;
            _currentTheme = value;
            NotifyStateChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyStateChanged();
        }
    }

    public event Action? OnChange;

    /// <summary>
    /// Apply multiple changes in a batch, raising OnChange only once.
    /// </summary>
    public void SetPreferences(Theme theme, string accentColor)
    {
        _currentTheme = theme;
        _accentColor = accentColor;
        NotifyStateChanged();
    }

    private void NotifyStateChanged() => OnChange?.Invoke();
}

@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<span class="theme-indicator" title="Current theme">
    @GetThemeIcon() <span style="color: @ThemeService.AccentColor;">@ThemeService.CurrentTheme</span>
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private string GetThemeIcon() => ThemeService.CurrentTheme switch
    {
        Theme.Light => "☀️",
        Theme.Dark => "🌙",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<button class="btn btn-sm btn-outline-secondary" @onclick="CycleTheme" title="Toggle theme">
    @GetThemeIcon()
</button>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void CycleTheme()
    {
        ThemeService.CurrentTheme = ThemeService.CurrentTheme switch
        {
            Theme.Light => Theme.Dark,
            Theme.Dark => Theme.System,
            _ => Theme.Light
        };
    }

    private string GetThemeIcon() => ThemeService.CurrentTheme switch
    {
        Theme.Light => "☀️",
        Theme.Dark => "🌙",
        _ => "💻"
    };

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h3>User Preferences</h3>

<div class="card mt-3" style="max-width: 500px;">
    <div class="card-body">
        <div class="mb-3">
            <label class="form-label fw-bold">Theme</label>
            <select class="form-select" @bind="SelectedTheme">
                @foreach (var theme in Enum.GetValues<Theme>())
                {
                    <option value="@theme">@theme</option>
                }
            </select>
        </div>

        <div class="mb-3">
            <label class="form-label fw-bold">Accent Color</label>
            <div class="d-flex align-items-center gap-2">
                <input type="color" class="form-control form-control-color"
                       @bind="SelectedAccentColor" />
                <span style="color: @SelectedAccentColor;">@SelectedAccentColor</span>
            </div>
        </div>

        <button class="btn btn-primary" @onclick="SavePreferences">
            Save Preferences
        </button>

        <div class="mt-3 p-2 border rounded" style="border-color: @ThemeService.AccentColor !important;">
            <small class="text-muted">Live preview:</small><br />
            Theme: <strong>@ThemeService.CurrentTheme</strong> |
            Accent: <span style="color: @ThemeService.AccentColor;">■ @ThemeService.AccentColor</span>
        </div>
    </div>
</div>

@code {
    private Theme SelectedTheme { get; set; }
    private string SelectedAccentColor { get; set; } = string.Empty;

    protected override void OnInitialized()
    {
        SelectedTheme = ThemeService.CurrentTheme;
        SelectedAccentColor = ThemeService.AccentColor;
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void SavePreferences()
    {
        ThemeService.SetPreferences(SelectedTheme, SelectedAccentColor);
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(() =>
        {
            SelectedTheme = ThemeService.CurrentTheme;
            SelectedAccentColor = ThemeService.AccentColor;
            StateHasChanged();
        });
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

